let kiwixReading=false;
let data={items:[]},view='home',scope='',limit=50;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const size=n=>n>=1073741824?(n/1073741824).toFixed(1)+' GiB':n>=1048576?(n/1048576).toFixed(1)+' MiB':n?Math.round(n/1024)+' KiB':'';
const descriptions={art:["Art gallery","Great works, quiet discoveries, and the stories behind them."],youtube:['YouTube','Online videos, inside Fieldstation.'],playlists:['Playlists','Pick a mood. Press play.'],codex:['Codex','An online coding assistant, running on your Pi.'],spotify:['Spotify & speaker EQ','Stream from your phone. Tune your speakers here.'],ask:["Ask the library","Answers from your PDFs and offline Wikipedia, with sources."],discover:["Popular & explore","Find a book or topic to start with."],catalogue:["Contents & search","Find a topic inside your PDF collection."],private:["Private files","Unlock your VeraCrypt container to browse its contents."],energy:['Energy at a glance.','Battery, solar input, and power use.'],home:['Knowledge, within reach.','Read, learn, listen, and watch. All in one place.'],library:['Your library','Reference books, health guides, and practical knowledge.'],education:['A classroom, offline.','Textbooks, learning wikis, and interactive simulations.'],languages:['Listen. Practise. Repeat.','French and Mandarin · Books, workbooks, and audio.'],movies:['Watch and listen.','Movies, music and course audio, grouped by collection.'],downloads:['Building your collection','Live file status. Incomplete files become available when finished.']};
let browseMode='reading';
function go(v,s=''){if(view==='youtube'&&v!=='youtube'){$('#youtube-player')?.replaceChildren();}if(['library','education','languages'].includes(v)){libraryLimit=48;librarySubject=s==='Practical & medical'?'General health & medicines':s==='Simulations'?'Interactive learning':'';libraryBook='';libraryDrawKey='';}if(v==='discover')delete $('#discover').dataset.built;closeKiwix(false);browseMode='reading';view=v;scope=s;limit=50;$('#search').value='';$('#filter').value=v==='downloads'?'all':'ready';history.replaceState(null,'','#'+v);render();window.scrollTo(0,0)}
function render(){if(kiwixReading)return;$('#art').hidden=view!=='art';$('#youtube').hidden=view!=='youtube';document.querySelector('footer span:last-child').textContent=view==='codex'?'Codex requires internet':['spotify','youtube'].includes(view)?'Internet required':'No internet needed';document.querySelectorAll('nav button[data-view]').forEach(b=>(b.classList.toggle('active',b.dataset.view===view),b.setAttribute('aria-current',b.dataset.view===view?'page':'false')));$('#heading').textContent=scope||descriptions[view][0];$('#subtitle').textContent=descriptions[view][1];$('#home').hidden=view!=='home';$('#browser').hidden=['art','home','energy','private','catalogue','discover','ask','spotify','codex','playlists','youtube'].includes(view);$('#energy').hidden=view!=='energy';$('#connection').textContent=data.libraryConnected?'Library connected':'Drive unavailable';$('#storage').textContent=data.storage?size(data.storage.free)+' free on library drive':'Connect your library drive';$('#notice').textContent=!data.libraryConnected?'The library drive is not connected. Reconnect it and refresh.':data.scanning?'Scanning connected folders; the catalogue will update automatically.':data.scanError?'Some files could not be scanned. Check the drive connection.':view==='languages'?'These FSI courses are historical. Some vocabulary and cultural references are dated.':view==='education'?'A broad learning collection; Singapore syllabus mapping and Pi simulation testing are still to come.':'';
 if(view==='art'){for(const id of ['home','browser','energy','private','catalogue','discover','ask','spotify','codex','playlists-page','youtube'])$('#'+id).hidden=true;renderArt();return;}
 if(view==='youtube'){for(const id of ['home','browser','energy','private','catalogue','discover','ask','spotify','codex','playlists-page'])$('#'+id).hidden=true;renderYouTube();return;}
 $('#playlists-page').hidden=view!=='playlists';if(view==='playlists'){for(const id of ['codex','spotify','ask','discover','catalogue','private'])$('#'+id).hidden=true;renderPlaylistsPage();return;}$('#codex').hidden=view!=='codex';if(view==='codex'){for(const id of ['spotify','ask','discover','catalogue','private'])$('#'+id).hidden=true;renderCodex();return;}$('#spotify').hidden=view!=='spotify';$('#ask').hidden=view!=='ask';$('#discover').hidden=view!=='discover';$('#catalogue').hidden=view!=='catalogue';$('#private').hidden=view!=='private';if(view==='spotify'){renderSpotify();return;} $('#ask').hidden=view!=='ask';if(view==='ask'){$('#discover').hidden=true;$('#catalogue').hidden=true;$('#private').hidden=true;renderAsk();return;} $('#discover').hidden=view!=='discover';if(view==='discover'){$('#catalogue').hidden=true;$('#private').hidden=true;renderDiscovery();return;} $('#catalogue').hidden=view!=='catalogue';if(view==='catalogue'){renderCatalogue();return} $('#private').hidden=view!=='private';if(view==='private'){renderPrivate();return} if(view==='energy'){renderEnergy();return} if(view==='home'){const tiles=[['◈','Art gallery','art','','Paintings · photography · world art'],['☆','Popular & explore','discover','','Book covers · fresh Wikipedia topics'],['♫','Playlists','playlists','','Curated mixes · one-tap playback'],['♫','Spotify & EQ','spotify','','Stream music · tune speakers'],['▤','Wikipedia & books','library','', 'Encyclopedia and reading'],['✚','Health & practical','library','Practical & medical','Guides for everyday resilience'],['▧','Education','education','','Grade 9–12 and beyond'],['文','Languages','languages','','French and Mandarin'],['▷','Media','movies','','Your existing media collection'],['⌁','Simulations','education','Simulations','Explore science by doing']];$('#home').innerHTML='<div class="tiles">'+tiles.map(t=>`<button class="tile" data-go="${t[2]}" data-scope="${t[3]}"><span class="icon">${t[0]}</span><span class="arrow">↗</span><strong>${t[1]}</strong><small>${t[4]}</small></button>`).join('')+'</div><div class="strip"><div><strong>'+data.items.filter(i=>i.status==='ready').length+' files ready</strong><p>'+data.items.filter(i=>i.status==='downloading').length+' downloading · '+data.items.filter(i=>i.status==='queued').length+' queued education files</p></div><button data-go="downloads">View downloads →</button></div>';$('#home').querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go,b.dataset.scope||''));refreshBattery();return}renderRows()}
let pdfSearchTimer, pdfSearchVersion=0;
function renderRows(){if(['library','education','languages'].includes(view)){renderLibrary(++pdfSearchVersion);return;}delete $('#results').dataset.library;renderBrowseModes();if(view==='movies'||browseMode==='listening'){++pdfSearchVersion;if(view==='movies')renderMediaLibrary();else renderMediaContents();return;}const searchVersion=++pdfSearchVersion;clearTimeout(pdfSearchTimer);let items=data.items.filter(i=>view==='downloads'?i.status!=='ready':view==='movies'?i.category==='Movies':view==='languages'?i.category==='Languages':view==='education'?i.category==='Education':!['Movies','Education','Languages'].includes(i.category));if(scope==='Simulations')items=items.filter(i=>i.folder.includes('Simulations'));if(scope==='Practical & medical')items=items.filter(i=>['Practical','Medical'].includes(i.category));let q=$('#search').value.toLowerCase();if(['library','education','languages'].includes(view)&&!q.trim()&&scope!=='Simulations'){ $('#search').placeholder='Search topics and PDF contents';$('#search').setAttribute('aria-label','Search topics and PDF contents');renderTopics(searchVersion);return;}delete $('#results').dataset.topics;items=items.filter(i=>(i.title+' '+i.folder).toLowerCase().includes(q));const f=$('#filter').value;if(f!=='all')items=items.filter(i=>i.status===f);$('#summary').textContent=items.length+' files'+(q?' matching your search':'');$('#results').innerHTML=items.slice(0,limit).map(i=>`<article class="row"><div class="format">${esc(i.format)}</div><div class="row-text"><div class="row-title">${esc(i.title)}</div><div class="meta">${esc(i.folder.replaceAll('\\',' / '))}${i.size?' · '+size(i.size):''}</div></div>${i.status==='ready'?`<button class="action" data-open="${i.id}">${['MP4','WEBM','MKV','AVI','MOV','MP3','M4A','WAV','OGG','M4V'].includes(i.format)?'Play':'Open'}</button>`:`<span class="status ${i.status}">${i.status==='downloading'?'Downloading':'Queued'}</span>`}</article>`).join('')||'<div class="empty">No files here yet. Try All files, or check Downloads.</div>';if(items.length>limit)$('#results').insertAdjacentHTML('beforeend','<button class="action" id="more">Show more</button>');$('#more')?.addEventListener('click',()=>{limit+=50;renderRows()});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openItem(data.items.find(i=>i.id===b.dataset.open)));
const pdfSearch=['library','education','languages'].includes(view);
$('#search').placeholder=pdfSearch?'Search titles and PDF contents':'Search titles and folders';
$('#search').setAttribute('aria-label',$('#search').placeholder);
if(pdfSearch&&q.trim()){
 $('#results').insertAdjacentHTML('beforeend','<section id="inline-pdf-results" aria-live="polite"><h2>Inside PDFs · all subjects</h2><p>Searching PDF text…</p></section>');
 pdfSearchTimer=setTimeout(()=>searchPdfContents(q,searchVersion),250);
}}
async function searchPdfContents(q,version){
 try{
 const response=await fetch('/api/catalogue?q='+encodeURIComponent(q));if(!response.ok)throw Error('PDF search unavailable');const result=await response.json();
 if(version!==pdfSearchVersion||!['library','education','languages'].includes(view))return;
 const target=$('#inline-pdf-results');if(!target)return;
 target.innerHTML='<h2>Inside PDFs · all subjects</h2><p>'+result.hits.length+(result.hits.length===result.limit?'+':'')+' page matches shown, grouped by book. Wikipedia and other ZIM archives use Kiwix search.</p>'+groupedPdfResults(result.hits,result.books);
 if(!result.hits.length)target.insertAdjacentHTML('beforeend','<p>No indexed PDF text matches. Scanned pages may need OCR.</p>');
 }catch(e){if(version===pdfSearchVersion&&$('#inline-pdf-results'))$('#inline-pdf-results').textContent=e.message;}
}

function openItem(i){if(['MP3','M4A','OGG','WAV','FLAC'].includes(i.format)){playAudio(i);return;}if(i.format==='ZIM'&&data.kiwix){openKiwix(i);return;}if(['MP4','WEBM','MKV','AVI','MOV','M4V'].includes(i.format)){openVideo(i);return}if(['PDF','HTML'].includes(i.format)){openDocument(i);return}$('#viewer-title').textContent=i.title;const body=$('#viewer-body');body.replaceChildren();if(i.format==='ZIM'){body.innerHTML=data.kiwix?'<p class="dialog-note">Open the Kiwix library to browse this archive and search its articles.</p><a class="action" href="http://127.0.0.1:8080" target="_blank" rel="noopener">Open Kiwix</a>':'<p class="dialog-note">This archive is downloaded. Kiwix Server needs to be installed and started before it can be browsed. The Pi setup guide includes this step.</p>';}else if(i.format==='EPUB'){body.innerHTML='<p class="dialog-note">Open this book with an EPUB reader on your device.</p><a class="action" href="'+i.url+'">Download book</a>'}else{const audio=['MP3','M4A','OGG','WAV'].includes(i.format);const player=document.createElement(audio?'audio':'video');player.controls=true;player.src=i.url;body.append(player);const p=document.createElement('p');p.className='dialog-note';p.textContent='If this format does not play in the browser, open its media address in VLC.';body.append(p);const button=document.createElement('button');button.className='action';button.textContent='Show address for VLC';button.onclick=()=>{const field=document.createElement('input');field.readOnly=true;field.value=location.origin+i.url;field.setAttribute('aria-label','Media address for VLC');body.append(field);field.select();button.disabled=true};body.append(button);player.onerror=()=>p.textContent='This browser cannot play this file. Use the media address in VLC.';}$('#viewer').showModal()}
$('#close').onclick=()=>$('#viewer').close();$('#viewer').addEventListener('close',()=>{$('#viewer-body').querySelectorAll('audio,video').forEach(p=>{p.pause();p.removeAttribute('src');p.load()});$('#viewer-body').replaceChildren()});document.querySelectorAll('nav button[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('.brand').onclick=e=>{e.preventDefault();go('home')};$('#search').oninput=()=>{limit=50;renderRows()};$('#filter').onchange=()=>{limit=50;renderRows()};async function refresh(){try{const r=await fetch('/api/library');if(!r.ok)throw Error();data=await r.json();render()}catch{$('#notice').textContent='The local library service is unavailable. Check that it is running, then refresh.'}}$('#refresh').onclick=refresh;const initial=location.hash.slice(1);if(descriptions[initial])view=initial;if(view==='downloads')$('#filter').value='all';refresh();setInterval(refresh,15000);
function renderEnergy(){renderLiveEnergy();}

const pendingVideoLaunches=new Set();
function openVideo(i){openInlineVideo(i);}
async function launchVideoExternal(i){
 if(pendingVideoLaunches.has(i.id))return;
 pendingVideoLaunches.add(i.id);
 try{
  const response=await fetch('/api/play',{method:'POST',headers:{'Content-Type':'application/json','X-Fieldstation':'play'},body:JSON.stringify({id:i.id})});
  const result=await response.json();if(!response.ok)throw new Error(result.error||'Unable to launch VLC.');
 }catch(error){
  let notice=document.getElementById('video-launch-error');
  if(!notice){notice=document.createElement('p');notice.id='video-launch-error';notice.className='dialog-note';notice.setAttribute('role','alert');$('#results').before(notice);}
  notice.textContent=i.title+': '+error.message;const inline=document.querySelector('#viewer-body .dialog-note');if(inline)inline.textContent=error.message;
  clearTimeout(notice.dismissTimer);notice.dismissTimer=setTimeout(()=>notice.remove(),10000);
 }finally{pendingVideoLaunches.delete(i.id);}
}

function openKiwix(item,articlePath=''){
 $('#share-article').hidden=false;$('#kiwix-start').hidden=false;$('#kiwix-start').textContent='Collection home';
 kiwixReading=true;document.body.classList.add('reading-kiwix');
 for(const id of ['art','home','catalogue','private','energy','browser','discover','ask','spotify','codex','playlists-page','youtube'])$('#'+id).hidden=true;
 $('#kiwix-reader').hidden=false;$('#kiwix-title').textContent=item.title;
 const frame=document.createElement('iframe');frame.title=item.title+' — offline reader';frame.setAttribute('sandbox','allow-scripts allow-same-origin allow-forms allow-downloads');
 frame.src='http://'+location.hostname+':8766/kiwix/content/'+encodeURIComponent(item.name.replace(/\.zim$/i,''))+'/'+articlePath;
 sharedArticlePath='/kiwix/content/'+encodeURIComponent(item.name.replace(/\.zim$/i,''))+'/'+articlePath;
 $('#kiwix-frame').replaceChildren(frame);
 $('#kiwix-start').onclick=()=>{frame.src='http://'+location.hostname+':8766/kiwix/content/'+encodeURIComponent(item.name.replace(/\.zim$/i,''))+'/';};
 $('#kiwix-return').focus();
}
function closeKiwix(redraw=true){
 if(!kiwixReading)return;kiwixReading=false;document.body.classList.remove('reading-kiwix','reader-maximized');$('#kiwix-maximize').textContent='Maximize';$('#kiwix-maximize').setAttribute('aria-pressed','false');$('#kiwix-reader').hidden=true;$('#kiwix-frame').replaceChildren();document.querySelectorAll('nav button[data-site]').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});if(redraw)render();
}
$('#kiwix-return').onclick=()=>closeKiwix();

$('#kiwix-maximize').onclick=()=>{const expanded=document.body.classList.toggle('reader-maximized');$('#kiwix-maximize').textContent=expanded?'Restore':'Maximize';$('#kiwix-maximize').setAttribute('aria-pressed',String(expanded));};

let youtubeRequest=0;
function renderYouTube(){
 const root=$('#youtube');if(root.dataset.built)return;root.dataset.built='1';
 root.innerHTML='<section class="spotify-card"><h2>Your YouTube</h2><p>Open YouTube here in the same window for your signed-in recommendations, subscriptions and history.</p><a class="action" href="https://www.youtube.com/">Open my YouTube</a><p class="meta">Sign in on YouTube once. Press Alt + Left to return to Fieldstation. The full YouTube site replaces this page; it cannot keep the Fieldstation sidebar.</p></section><h2>Quick search without signing in</h2><form id="youtube-search-form" class="tools"><label class="search"><input id="youtube-query" type="search" placeholder="Search YouTube" aria-label="Search YouTube"></label><button class="action">Search</button></form><div class="tools" id="youtube-categories">'+['Science & nature','Music','Travel','Cooking','Learning'].map(q=>'<button class="action secondary" data-yt-query="'+q+'">'+q+'</button>').join('')+'</div><p id="youtube-message" role="status"></p><div id="youtube-player"></div><div id="youtube-results" class="video-grid"></div>';
 $('#youtube-search-form').onsubmit=e=>{e.preventDefault();loadYouTube($('#youtube-query').value)};
 root.querySelectorAll('[data-yt-query]').forEach(b=>b.onclick=()=>{$('#youtube-query').value=b.dataset.ytQuery;loadYouTube(b.dataset.ytQuery)});
 loadYouTube('science nature documentary');
}
async function loadYouTube(q){
 const request=++youtubeRequest;$('#youtube-message').textContent='Searching YouTube…';
 try{const r=await fetch('/api/youtube?q='+encodeURIComponent(q));const result=await r.json();if(!r.ok)throw Error(result.error);if(request!==youtubeRequest)return;
 $('#youtube-message').textContent='Online results · '+result.videos.length+' videos';$('#youtube-results').innerHTML=result.videos.map((v,n)=>'<article class="video-card"><button class="video-preview" data-youtube="'+n+'" aria-label="Play '+esc(v.title)+'"><img loading="lazy" src="https://i.ytimg.com/vi/'+v.id+'/hqdefault.jpg" alt=""></button><div class="row-text"><div class="row-title">'+esc(v.title)+'</div><div class="meta">'+esc([v.channel,v.duration,v.views].filter(Boolean).join(' · '))+'</div></div><button class="action" data-youtube="'+n+'">Watch</button></article>').join('');
 $('#youtube-results').querySelectorAll('[data-youtube]').forEach(b=>b.onclick=()=>{const video=result.videos[Number(b.dataset.youtube)],frame=document.createElement('iframe');frame.src='https://www.youtube-nocookie.com/embed/'+video.id;frame.title=video.title;frame.allow='autoplay; encrypted-media; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';frame.className='youtube-frame';$('#youtube-player').replaceChildren(frame);const title=document.createElement('h2');title.textContent=video.title;const close=document.createElement('button');close.className='action secondary';close.textContent='Close video';close.onclick=()=>$('#youtube-player').replaceChildren();$('#youtube-player').prepend(title,close);$('#youtube-player').scrollIntoView({block:'start'});});
 }catch(e){if(request===youtubeRequest){$('#youtube-message').textContent=e.message;$('#youtube-results').replaceChildren();}}
}
